<?php
namespace App\Policies;use App\Models\{User,StickerStock};final class StickerStockPolicy{private function a(User$u):bool{return$u->memberships()->where('status','ACTIVE')->whereIn('role_code',['SYSTEM_ADMIN','PLATFORM_ADMIN','STICKER_CUSTODIAN'])->exists();}public function viewAny(User$u):bool{return$this->a($u);}public function view(User$u,StickerStock$m):bool{return$this->a($u)&&$m->custodian_tenant_id===app(\App\Domain\Tenancy\TenantContext::class)->id();}public function create(User$u):bool{return$this->a($u);}public function update(User$u,StickerStock$m):bool{return$this->view($u,$m);}public function delete(User$u,StickerStock$m):bool{return false;}}
